import heapq

def match(orders):
    book_buy = []   # heap of (-price, seq, id)
    book_sell = []  # heap of (price, seq, id)
    order_info = {}  # id -> [side, price, qty_remaining, seq, status]
    trades = []
    seq_counter = 0

    def can_match(incoming_side, incoming_price, resting_price):
        if incoming_price is None:
            return True
        if incoming_side == 'buy':
            return incoming_price >= resting_price
        else:
            return incoming_price <= resting_price

    for o in orders:
        typ = o[0]
        if typ == 'cancel':
            oid = o[1]
            if oid in order_info and order_info[oid][4] == 'active':
                order_info[oid][4] = 'cancelled'
            continue

        if typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            _, oid, side, price, qty = o

        seq_counter += 1
        seq = seq_counter
        order_info[oid] = [side, price, qty, seq, 'active']

        remaining = qty
        heap = book_sell if side == 'buy' else book_buy

        while remaining > 0 and heap:
            if side == 'buy':
                resting_price, oseq, oid2 = heap[0]
            else:
                neg_price, oseq, oid2 = heap[0]
                resting_price = -neg_price

            info2 = order_info.get(oid2)
            if info2 is None or info2[4] != 'active' or info2[2] <= 0:
                heapq.heappop(heap)
                continue

            if not can_match(side, price, resting_price):
                break

            trade_qty = min(remaining, info2[2])
            trade_price = resting_price

            if side == 'buy':
                trades.append([oid, oid2, trade_price, trade_qty])
            else:
                trades.append([oid2, oid, trade_price, trade_qty])

            remaining -= trade_qty
            info2[2] -= trade_qty

            if info2[2] == 0:
                info2[4] = 'filled'
                heapq.heappop(heap)
            # if info2[2] > 0, remaining must be 0, loop will end

        if typ == 'limit':
            order_info[oid][2] = remaining
            if remaining > 0:
                if side == 'buy':
                    heapq.heappush(book_buy, (-price, seq, oid))
                else:
                    heapq.heappush(book_sell, (price, seq, oid))
            else:
                order_info[oid][4] = 'filled'
        else:
            # ioc or market: discard remainder
            order_info[oid][2] = remaining
            order_info[oid][4] = 'filled' if remaining == 0 else 'cancelled'

    return trades

